effect.shader:
#define EPS 0.00001
#define PI 3.14159265359
#define TAU 6.28318530718
vec2 applyEdge(vec2 uv, float mode) {
if (mode < 1.5) return uv;
if (mode < 2.5) return fract(uv);
if (mode < 3.5) {
vec2 r = uv;
r.x = (mod(floor(r.x), 2.0) == 0.0) ? fract(r.x) : 1.0 - fract(r.x);
r.y = (mod(floor(r.y), 2.0) == 0.0) ? fract(r.y) : 1.0 - fract(r.y);
return r;
}
return clamp(uv, 0.0, 1.0);
}
float isInBounds(vec2 uv) {
return step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
}
vec2 warpFisheye(vec2 p, float amount, float radius, float softness) {
float dist = length(p);
float r = radius * 0.5;
if (dist < EPS) return p;
float amt = amount / 100.0;
float normDist = dist / max(r, EPS);
float power = 1.0 + amt * 2.0;
float warpedDist = pow(normDist, power) * r;
float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
float finalDist = mix(dist, warpedDist, blend);
return p * (finalDist / max(dist, EPS));
}
vec2 warpAntiFisheye(vec2 p, float amount, float radius, float softness) {
float dist = length(p);
float r = radius * 0.5;
if (dist < EPS) return p;
float amt = amount / 100.0;
float normDist = dist / max(r, EPS);
float power = 1.0 / max(1.0 + amt * 2.0, 0.01);
float warpedDist = pow(normDist, power) * r;
float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
float finalDist = mix(dist, warpedDist, blend);
return p * (finalDist / max(dist, EPS));
}
vec2 warpBarrel(vec2 p, float k1v, float k2v, float k3v) {
float r2 = dot(p, p);
float r4 = r2 * r2;
float r6 = r4 * r2;
float distortion = 1.0 + k1v * r2 + k2v * r4 + k3v * r6;
return p * distortion;
}
vec2 warpPincushion(vec2 p, float amount) {
float dist = length(p);
if (dist < EPS) return p;
float amt = -amount / 100.0;
float r2 = dot(p, p);
float distortion = 1.0 + amt * r2 + amt * amt * r2 * r2;
return p * distortion;
}
vec2 warpBulge(vec2 p, float amount, float radius, float softness) {
float dist = length(p);
float r = radius * 0.5;
if (dist < EPS) return p;
float amt = amount / 100.0;
float normDist = dist / max(r, EPS);
float bulge = 1.0 + amt * (1.0 - normDist * normDist);
bulge = max(bulge, 0.01);
float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
float scale = mix(1.0, bulge, blend);
return p * scale;
}
vec2 warpBullseye(vec2 p, float amount, float radius) {
float dist = length(p);
float r = radius * 0.5;
if (dist < EPS) return p;
float amt = amount / 100.0;
float normDist = dist / max(r, EPS);
float ringDist = sin(normDist * PI * 3.0) * amt * 0.3;
float finalDist = dist + ringDist * r;
return p * (finalDist / max(dist, EPS));
}
vec2 warpUpperShell(vec2 p, float amount, float radius, float softness) {
float dist = length(p);
float r = radius * 0.5;
if (dist < EPS) return p;
float amt = amount / 100.0;
float topMask = smoothstep(-0.1, 0.1, -p.y);
float normDist = dist / max(r, EPS);
float power = 1.0 + amt * 2.0 * topMask;
float warpedDist = pow(normDist, power) * r;
float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
float finalDist = mix(dist, warpedDist, blend * topMask);
return p * (finalDist / max(dist, EPS));
}
vec2 warpLowerShell(vec2 p, float amount, float radius, float softness) {
float dist = length(p);
float r = radius * 0.5;
if (dist < EPS) return p;
float amt = amount / 100.0;
float bottomMask = smoothstep(-0.1, 0.1, p.y);
float normDist = dist / max(r, EPS);
float power = 1.0 + amt * 2.0 * bottomMask;
float warpedDist = pow(normDist, power) * r;
float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
float finalDist = mix(dist, warpedDist, blend * bottomMask);
return p * (finalDist / max(dist, EPS));
}
vec2 warpSpherize(vec2 p, float amount, float radius) {
float dist = length(p);
float r = radius * 0.5;
if (dist < EPS || dist > r) return p;
float amt = amount / 100.0;
float normDist = dist / r;
float z = sqrt(max(1.0 - normDist * normDist, 0.0));
float sphereDist = asin(normDist) / max(PI * 0.5, EPS);
float finalDist = mix(normDist, sphereDist, amt) * r;
return p * (finalDist / max(dist, EPS));
}
vec2 warpTwirl(vec2 p, float angle, float radius) {
float dist = length(p);
float r = radius * 0.5;
if (dist < EPS) return p;
float angRad = angle * PI / 180.0;
float normDist = clamp(dist / max(r, EPS), 0.0, 1.0);
float twirlAmt = angRad * (1.0 - normDist);
float cs = cos(twirlAmt);
float sn = sin(twirlAmt);
return vec2(p.x * cs - p.y * sn, p.x * sn + p.y * cs);
}
vec2 warpWave(vec2 p, float amp, float freq, float phase, float angle, float time) {
float angRad = angle * PI / 180.0;
float phaseRad = phase * PI / 180.0;
vec2 dir = vec2(cos(angRad), sin(angRad));
vec2 perp = vec2(-dir.y, dir.x);
float projection = dot(p, dir);
float waveVal = sin(projection * freq * TAU + phaseRad + time * TAU) * amp * 0.01;
return p + perp * waveVal;
}
vec2 warpRipple(vec2 p, float amp, float freq, float phase, float decay, float time) {
float dist = length(p);
if (dist < EPS) return p;
float phaseRad = phase * PI / 180.0;
float decayFactor = 1.0;
if (decay > 0.5) {
decayFactor = exp(-dist * decay * 0.1);
}
float rippleVal = sin(dist * freq * TAU - phaseRad - time * TAU) * amp * 0.01 * decayFactor;
vec2 dir = p / dist;
return p + dir * rippleVal;
}
void main() {
vec2 uv = acScreenNorm;
float em = float(edgeMode);
float wm = float(warpMode);
vec2 imgSize = inputImg.size;
float aspect = imgSize.x / max(imgSize.y, 1.0);
vec4 original = texture2DCv(inputImg.texture, uv);
vec3 baseRGB = original.rgb;
vec2 center = vec2(0.5 + warpCenter.x, 0.5 + warpCenter.y);
vec2 p = uv - center;
p.x *= aspect * aspectX;
p.y *= aspectY;
float radius = warpRadius / 100.0;
float softness = warpSoftness;
float amt = warpAmount;
float t = acTime;
vec2 warped = p;
if (wm < 1.5) {
warped = warpFisheye(p, amt, radius, softness);
} else if (wm < 2.5) {
warped = warpAntiFisheye(p, amt, radius, softness);
} else if (wm < 3.5) {
warped = warpBarrel(p, k1 + amt * 0.01, k2, k3);
} else if (wm < 4.5) {
warped = warpPincushion(p, amt);
} else if (wm < 5.5) {
warped = warpBulge(p, amt, radius, softness);
} else if (wm < 6.5) {
warped = warpBullseye(p, amt, radius);
} else if (wm < 7.5) {
warped = warpUpperShell(p, amt, radius, softness);
} else if (wm < 8.5) {
warped = warpLowerShell(p, amt, radius, softness);
} else if (wm < 9.5) {
warped = warpSpherize(p, amt, radius);
} else if (wm < 10.5) {
warped = warpTwirl(p, twirlAngle + amt, twirlRadius / 100.0);
} else if (wm < 11.5) {
warped = warpWave(p, waveAmplitude + abs(amt) * 0.5, waveFrequency, wavePhase, waveAngle, t * waveSpeed);
} else {
warped = warpRipple(p, rippleAmplitude + abs(amt) * 0.5, rippleFrequency, ripplePhase, rippleDecay, t * rippleSpeed);
}
if (abs(bendX) > 0.5 || abs(bendY) > 0.5 || abs(bendUniform) > 0.5) {
float bx = (bendX + bendUniform) / 100.0;
float by = (bendY + bendUniform) / 100.0;
warped.x += bx * warped.y * warped.y;
warped.y += by * warped.x * warped.x;
}
if (wm > 3.5 || wm < 2.5) {
if (abs(k1) > EPS || abs(k2) > EPS || abs(k3) > EPS) {
float r2 = dot(warped, warped);
float r4 = r2 * r2;
float r6 = r4 * r2;
float kDist = 1.0 + k1 * r2 + k2 * r4 + k3 * r6;
warped *= kDist;
}
}
warped.x /= aspect * aspectX;
warped.y /= aspectY;
vec2 warpedUV = warped + center;
float chromaStr = chromaWarp / 100.0;
vec3 result;
if (chromaStr > EPS) {
vec2 pR = uv - center;
pR.x *= aspect * aspectX;
pR.y *= aspectY;
vec2 pB = pR;
float rAmt = amt * (1.0 + chromaStr * 0.3);
float bAmt = amt * (1.0 - chromaStr * 0.3);
vec2 warpedR = pR;
vec2 warpedB = pB;
if (wm < 1.5) {
warpedR = warpFisheye(pR, rAmt, radius, softness);
warpedB = warpFisheye(pB, bAmt, radius, softness);
} else if (wm < 2.5) {
warpedR = warpAntiFisheye(pR, rAmt, radius, softness);
warpedB = warpAntiFisheye(pB, bAmt, radius, softness);
} else if (wm < 3.5) {
warpedR = warpBarrel(pR, k1 + rAmt * 0.01, k2, k3);
warpedB = warpBarrel(pB, k1 + bAmt * 0.01, k2, k3);
} else if (wm < 5.5) {
warpedR = warpBulge(pR, rAmt, radius, softness);
warpedB = warpBulge(pB, bAmt, radius, softness);
} else {
warpedR = warped;
warpedB = warped;
}
if (abs(bendX) > 0.5 || abs(bendY) > 0.5 || abs(bendUniform) > 0.5) {
float bx = (bendX + bendUniform) / 100.0;
float by = (bendY + bendUniform) / 100.0;
warpedR.x += bx * warpedR.y * warpedR.y;
warpedR.y += by * warpedR.x * warpedR.x;
warpedB.x += bx * warpedB.y * warpedB.y;
warpedB.y += by * warpedB.x * warpedB.x;
}
warpedR.x /= aspect * aspectX;
warpedR.y /= aspectY;
warpedB.x /= aspect * aspectX;
warpedB.y /= aspectY;
vec2 uvR = warpedR + center;
vec2 uvB = warpedB + center;
float inR = (em < 1.5) ? isInBounds(uvR) : 1.0;
float inG = (em < 1.5) ? isInBounds(warpedUV) : 1.0;
float inB = (em < 1.5) ? isInBounds(uvB) : 1.0;
uvR = applyEdge(uvR, em); uvR = clamp(uvR, 0.0, 1.0);
vec2 uvG = applyEdge(warpedUV, em); uvG = clamp(uvG, 0.0, 1.0);
uvB = applyEdge(uvB, em); uvB = clamp(uvB, 0.0, 1.0);
result.r = texture2DCv(inputImg.texture, uvR).r * inR;
result.g = texture2DCv(inputImg.texture, uvG).g * inG;
result.b = texture2DCv(inputImg.texture, uvB).b * inB;
} else {
float inBounds = (em < 1.5) ? isInBounds(warpedUV) : 1.0;
warpedUV = applyEdge(warpedUV, em);
warpedUV = clamp(warpedUV, 0.0, 1.0);
result = texture2DCv(inputImg.texture, warpedUV).rgb * inBounds;
}
result = mix(baseRGB, result, globalMix);
result = clamp(result, 0.0, 1.0);
gl_FragColor = vec4(result, original.a);
}
